from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENTS = Decimal("0.01")
_HUNDRED = Decimal("100")


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric coercion for supplied numeric fields."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    """Round monetary values using legacy half-up cent rounding."""
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """
    Recompute live order-line extensions and the order total.

    Inputs are not mutated.  Soft-deleted lines retain their existing values,
    and soft-deleted or cancelled orders are returned unchanged.
    """
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal("0")

    for line in new_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        extension = _cents(_numeric(line.get("QTY", "")) * _numeric(line.get("UNIT_PRC", "")))
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted = _cents(
        total * (_HUNDRED - _numeric(order.get("DISC_PCT", ""))) / _HUNDRED
    )

    if _numeric(order.get("TOT_AMT", "")) != discounted:
        new_order["TOT_AMT"] = float(discounted)
        return new_order, new_lines, [("ORD_RETOTAL", order.get("ORD_ID"))]

    return new_order, new_lines, []
